        <RouterLink :to="localizedPath('experiences')">{{copy.back}}</RouterLink>
      </section>
      <template v-else>
        <section class="detail-hero">
          <img :src="villa.images[0].url" :alt="villa.name" />
          <div class="detail-hero__overlay"></div>
          <div class="detail-shell detail-hero__content">
            <RouterLink :to="localizedPath('experiences')" class="detail-back"><ArrowLeft /> {{copy.allVillas}}</RouterLink>
            <div><span><MapPin />{{ villa.destination }}, {{copy.mexico}}</span><h1>{{ villa.name }}</h1><a :href="whatsappHref" target="_blank" rel="noreferrer" class="detail-button detail-button--gold">{{copy.availability}} <ArrowUpRight /></a></div>
          </div>
        </section>

        <section v-if="hasPropertyFacts" class="detail-facts"><div class="detail-shell facts-grid"><span v-if="villa.guests"><Users/><strong>{{villa.guests}}</strong> {{copy.guests}}</span><span v-if="villa.rooms"><BedDouble/><strong>{{villa.rooms}}</strong> {{copy.rooms}}</span><span v-if="villa.baths"><Bath/><strong>{{villa.baths}}</strong> {{copy.baths}}</span><span v-if="villa.area"><strong>{{villa.area}}</strong> m²</span><span v-if="villa.minimumStay"><strong>{{villa.minimumStay}}</strong></span></div></section>

        <section class="detail-shell detail-intro"><span class="detail-kicker">{{copy.privateResidence}}</span><div><h2>{{ localBadge }}</h2><p>{{copy.description}}</p></div></section>

        <section class="detail-shell detail-gallery-section">
          <header><span>{{copy.gallery}}</span><p>{{ villa.images.length }} {{copy.photos}}</p></header>
          <div class="detail-gallery" :class="{ 'detail-gallery--single': villa.images.length === 1 }">
            <button v-for="(image,index) in previewImages" :key="image.name" type="button" @click="openLightbox(index)"><img :src="image.url" :alt="`${villa.name}, fotografía ${index + 1}`" :loading="index ? 'lazy' : 'eager'" /></button>
          </div>
          <div class="gallery-filters"><button v-for="item in copy.galleryFilters" :key="item" type="button">{{item}}</button></div>
          <button class="all-photos" type="button" @click="openLightbox(0)"><Images /> {{copy.allPhotos}}</button>
