          </div>
        </section>

        <section v-if="relatedVillas.length" class="related detail-shell"><header><span class="detail-kicker">{{copy.privateCollection}}</span><h2>{{copy.related}}</h2></header><div class="related-grid"><article v-for="item in relatedVillas" :key="item.slug"><RouterLink :to="detailPath(item.slug)"><img :src="item.coverUrl" :alt="item.name" loading="lazy"></RouterLink><small><MapPin/>{{item.destination}}</small><h3>{{item.name}}</h3><RouterLink :to="detailPath(item.slug)">{{copy.viewProperty}} <ArrowRight/></RouterLink></article></div></section>

        <section class="planning detail-shell"><header><span class="detail-kicker">Sky Group</span><h2>{{copy.planTitle}}</h2></header><div class="planning-grid"><article><Plane/><div><h3>{{copy.privateFlight}}</h3><p>{{copy.flightText}}</p><RouterLink :to="localizedPath('reserva')">{{copy.quoteFlight}} <ArrowRight/></RouterLink></div></article><article><House/><div><h3>{{copy.exclusiveStay}}</h3><p>{{copy.stayText}}</p><a :href="whatsappHref" target="_blank">{{copy.availability}} <ArrowRight/></a></div></article></div></section>

        <transition name="bar"><div v-if="showBookingBar" class="booking-bar"><div><small>{{villa.destination}}</small><strong>{{villa.name}}</strong></div><span>{{copy.conciergeRate}}</span><a :href="whatsappHref" target="_blank">{{copy.availability}}</a></div></transition>

        <a :href="whatsappHref" target="_blank" rel="noreferrer" class="mobile-sticky"><MessageCircle /> {{copy.checkAvailability}}</a>
      </template>

      <Teleport to="body">
        <div v-if="lightboxOpen" class="lightbox" role="dialog" aria-modal="true" :aria-label="`Galería de ${villa.name}`">
          <button class="lightbox__close" type="button" aria-label="Cerrar galería" @click="closeLightbox"><X /></button>
          <button class="lightbox__nav lightbox__nav--prev" type="button" aria-label="Foto anterior" @click="previous"><ChevronLeft /></button>
          <img :src="villa.images[activeImage].url" :alt="`${villa.name}, fotografía ${activeImage + 1}`" />
          <button class="lightbox__nav lightbox__nav--next" type="button" aria-label="Foto siguiente" @click="next"><ChevronRight /></button>
          <span class="lightbox__count">{{ activeImage + 1 }} / {{ villa.images.length }}</span>
