<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute } from "vue-router";
import { ArrowLeft, ArrowRight, ArrowUpRight, Bath, BedDouble, Check, ChefHat, ChevronLeft, ChevronRight, House, Images, MapPin, MessageCircle, Plane, Users, Waves, X } from "lucide-vue-next";
import MainLayout from "../layouts/MainLayout.vue";
import { useLocalizedNavigation } from "../composables/useLocalizedNavigation";
import { getVilla, getVillas, subscribeToVillas } from "../services/villas.service";

const route = useRoute(); const { locale, localizedPath } = useLocalizedNavigation();
const villa = ref(null); const relatedVillas = ref([]); const loading = ref(true); const error = ref(false); const lightboxOpen = ref(false); const activeImage = ref(0); const showBookingBar = ref(false);
const previewImages = computed(() => villa.value?.images.slice(0, 5) || []);
const hasPropertyFacts=computed(()=>Boolean(villa.value?.guests||villa.value?.rooms||villa.value?.baths||villa.value?.area||villa.value?.minimumStay));
const copy=computed(()=>locale.value==='es-mx'?{loading:'Cargando villa...',loadError:'No pudimos cargar esta propiedad.',unavailable:'Esta villa no está disponible.',back:'Volver a experiencias',allVillas:'Todas las villas',mexico:'México',availability:'Solicitar disponibilidad',checkAvailability:'Consultar disponibilidad',quoteFlight:'Cotizar vuelo privado',commercialTitle:'Tu viaje comienza antes de despegar',commercialText:'Nos encargamos del vuelo privado, hospedaje, transporte ejecutivo, concierge y experiencias personalizadas para que únicamente disfrutes el destino.',guests:'huéspedes',rooms:'habitaciones',baths:'baños',pool:'Piscina privada',chef:'Chef disponible',privateResidence:'Residencia privada',caribbean:'frente al Caribe.',description:'Una residencia privada seleccionada para ofrecer confort, privacidad absoluta y una experiencia excepcional en México.',openSpaces:'Espacios abiertos y una estancia diseñada para familias y grupos.',gallery:'Galería de la propiedad',photos:'fotografías',allPhotos:'Ver todas las fotografías',galleryFilters:['Todas','Interior','Recámaras','Piscina','Playa','Vista aérea','Experiencias'],amenities:'Amenidades premium',amenitiesTitle:'Todo lo necesario para una estancia extraordinaria.',destinationExperiences:'Experiencias',moments:'Vive el destino como nunca antes',experiences:['Chef privado','Yacht charter','Pesca deportiva','Golf','Cenotes','Helicóptero','Jet privado','Spa','Transporte ejecutivo'],location:'Ubicación',locationItems:['15 min del aeropuerto','10 min de la zona hotelera','5 min de restaurantes','Acceso directo a playa'],viewLocation:'Ver ubicación',privateCollection:'Colección privada',related:'También podría interesarte',viewProperty:'Ver propiedad',planTitle:'Planea tu experiencia completa',privateFlight:'Vuelo privado',flightText:'Coordinamos tu vuelo desde cualquier ciudad.',exclusiveStay:'Hospedaje exclusivo',stayText:'Reserva tu estancia con concierge personalizado.',conciergeRate:'Tarifa personalizada por concierge'}:{loading:'Loading villa...',loadError:'We could not load this property.',unavailable:'This villa is unavailable.',back:'Back to experiences',allVillas:'All villas',mexico:'Mexico',availability:'Request availability',checkAvailability:'Check availability',quoteFlight:'Quote a private flight',commercialTitle:'Your journey begins before takeoff',commercialText:'We coordinate private aviation, accommodations, executive transportation, concierge and personalized experiences so you can simply enjoy the destination.',guests:'guests',rooms:'bedrooms',baths:'bathrooms',pool:'Private pool',chef:'Chef available',privateResidence:'Private residence',caribbean:'on the Caribbean.',description:'A private residence selected to offer comfort, absolute privacy and an exceptional experience in Mexico.',openSpaces:'Open spaces and a stay designed for families and groups.',gallery:'Property gallery',photos:'photos',allPhotos:'View all photographs',galleryFilters:['All','Interior','Bedrooms','Pool','Beach','Aerial view','Experiences'],amenities:'Premium amenities',amenitiesTitle:'Everything needed for an extraordinary stay.',destinationExperiences:'Experiences',moments:'Experience the destination like never before',experiences:['Private chef','Yacht charter','Sport fishing','Golf','Cenotes','Helicopter','Private jet','Spa','Executive transportation'],location:'Location',locationItems:['15 min from the airport','10 min from the hotel zone','5 min from restaurants','Direct beach access'],viewLocation:'View location',privateCollection:'Private collection',related:'You may also be interested in',viewProperty:'View property',planTitle:'Plan your complete experience',privateFlight:'Private flight',flightText:'We coordinate your flight from any city.',exclusiveStay:'Exclusive accommodation',stayText:'Book your stay with a dedicated concierge.',conciergeRate:'Personalized concierge rate'});
const amenityTranslations={Piscina:'Pool',Chef:'Chef',Seguridad:'Security',Terraza:'Terrace',Estacionamiento:'Parking',Bar:'Bar',BBQ:'BBQ',Cinema:'Cinema',Gym:'Gym',Jacuzzi:'Jacuzzi','Beach Club':'Beach Club',WiFi:'WiFi','Frente al mar':'Oceanfront','Piscina privada':'Private pool',Concierge:'Concierge','Diseño contemporáneo':'Contemporary design','Frente al Caribe':'Caribbeanfront','Playa privada':'Private beach','Vistas panorámicas':'Panoramic views','Jardines tropicales':'Tropical gardens','Espacios abiertos':'Open spaces',Naturaleza:'Nature','Diseño boutique':'Boutique design','Vista panorámica':'Panoramic view','Piscina infinita':'Infinity pool','Acceso directo al mar':'Direct ocean access','Vista al Caribe':'Caribbean view','Espacios amplios':'Spacious interiors'};
const localizedAmenities=computed(()=>villa.value?.amenities.map(item=>locale.value==='en-us'?(amenityTranslations[item]||item):item)||[]);
const badgeTranslations={'Beach club privado':'Private beach club','Arquitectura contemporánea':'Contemporary architecture','Frente al mar':'Oceanfront','Villa de lujo':'Luxury villa','Experiencia boutique':'Boutique experience','Vista al océano':'Ocean view','Frente a la playa':'Beachfront'};
const translatedValue=(dictionary,value)=>{const match=Object.entries(dictionary).find(([key])=>key.localeCompare(String(value||''),undefined,{sensitivity:'base'})===0);return match?.[1]||value};
const localBadge=computed(()=>locale.value==='en-us'?translatedValue(badgeTranslations,villa.value?.badge):villa.value?.badge);
const openMapsLabel=computed(()=>locale.value==='es-mx'?'Abrir en Google Maps':'Open in Google Maps');
const regionLabel=computed(()=>['Puerto Vallarta'].includes(villa.value?.destination)?'Jalisco':'Quintana Roo');
const mapQuery=computed(()=>`${villa.value?.destination}, ${regionLabel.value}, Mexico`);
const mapHref=computed(()=>`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(mapQuery.value)}`);
const mapEmbedHref=computed(()=>`https://www.google.com/maps?q=${encodeURIComponent(mapQuery.value)}&z=12&output=embed`);
const detailPath=slug=>`/${locale.value}/experiencias/${slug}`;
const whatsappHref = computed(() => `https://wa.me/525586186576?text=${encodeURIComponent(locale.value==='es-mx'?`Hola, estoy interesado en ${villa.value?.name} en ${villa.value?.destination}. ¿Me pueden compartir disponibilidad?`:`Hello, I am interested in ${villa.value?.name} in ${villa.value?.destination}. Could you share availability?`)}`);
const openLightbox = (index) => { activeImage.value = index; lightboxOpen.value = true; };
const closeLightbox = () => { lightboxOpen.value = false; };
const previous = () => { activeImage.value = (activeImage.value - 1 + villa.value.images.length) % villa.value.images.length; };
const next = () => { activeImage.value = (activeImage.value + 1) % villa.value.images.length; };
const handleKeys = (event) => { if (!lightboxOpen.value) return; if (event.key === 'Escape') closeLightbox(); if (event.key === 'ArrowLeft') previous(); if (event.key === 'ArrowRight') next(); };
watch(lightboxOpen, (open) => { document.body.style.overflow = open ? 'hidden' : ''; });
const handleScroll=()=>{showBookingBar.value=window.scrollY>window.innerHeight*.85};
const refreshVilla=async()=>{try{const [current,all]=await Promise.all([getVilla(String(route.params.slug)),getVillas()]);villa.value=current;relatedVillas.value=all.filter(item=>item.slug!==route.params.slug).slice(0,4);error.value=false}catch(cause){console.error('Unable to load villa',cause);error.value=true}finally{loading.value=false}};
let unsubscribeVillas=()=>{};
onMounted(async () => { window.addEventListener('keydown', handleKeys); window.addEventListener('scroll',handleScroll,{passive:true}); await refreshVilla(); unsubscribeVillas=subscribeToVillas(refreshVilla); });
onBeforeUnmount(() => { unsubscribeVillas(); window.removeEventListener('keydown', handleKeys); window.removeEventListener('scroll',handleScroll); document.body.style.overflow = ''; });
</script>

